      Entries<K, V> newEntries1 = new Entries<>(this);
      Entries<K, V> newEntries2 = new Entries<>(this);
      entries1 = newEntries1;
      entries2 = newEntries2;
    }
    Entries<K, V> e1 = entries1;
    Entries<K, V> e2 = entries2;/' gdx/src/com/badlogic/gdx/utils/ArrayMap.java && sed -i 's/if (!entries1.valid) {/if (!e1.valid) {
      e1.index = 0;
      e1.valid = true;
      e2.valid = false;
      return e1;
    }
    e2.index = 0;
    e2.valid = true;
    e1.valid = false;
    return e2;/' gdx/src/com/badlogic/gdx/utils/ArrayMap.java && sed -i '555,571s/values1 == null) {/values1 == null) {
      Values<V> newValues1 = new Values<>(this);
      Values<V> newValues2 = new Values<>(this);
      values1 = newValues1;
      values2 = newValues2;
    }
    Values<V> v1 = values1;
    Values<V> v2 = values2;/' gdx/src/com/badlogic/gdx/utils/ArrayMap.java && sed -i 's/if (!values1.valid) {/if (!v1.valid) {
      v1.index = 0;
      v1.valid = true;
      v2.valid = false;
      return v1;
    }
    v2.index = 0;
    v2.valid = true;
    v1.valid = false;
    return v2;/' gdx/src/com/badlogic/gdx/utils/ArrayMap.java && sed -i '582,598s/keys1 == null) {/keys1 == null) {
      Keys<K> newKeys1 = new Keys<>(this);
      Keys<K> newKeys2 = new Keys<>(this);
      keys1 = newKeys1;
      keys2 = newKeys2;
    }
    Keys<K> k1 = keys1;
    Keys<K> k2 = keys2;/' gdx/src/com/badlogic/gdx/utils/ArrayMap.java && sed -i 's/if (!keys1.valid) {/if (!k1.valid) {
      k1.index = 0;
      k1.valid = true;
      k2.valid = false;
      return k1;
    }
    k2.index = 0;
    k2.valid = true;
    k1.valid = false;
    return k2;/' gdx/src/com/badlogic/gdx/utils/ArrayMap.java && nl -ba gdx/src/com/badlogic/gdx/utils/ArrayMap.java | sed -n "520,610p"
